import {
  createElement,
  type ElementType,
  type HTMLAttributes,
  type PointerEvent,
  type ReactNode,
} from "react";
import "./liquid-glass.css";

type LiquidGlassElement =
  | "aside"
  | "div"
  | "footer"
  | "form"
  | "header"
  | "nav"
  | "section";

export interface LiquidGlassProps extends HTMLAttributes<HTMLElement> {
  as?: LiquidGlassElement;
  children: ReactNode;
  tone?: "dark" | "light";
  intensity?: "strong" | "soft";
  interactive?: boolean;
}

function setSpecularPosition(event: PointerEvent<HTMLElement>) {
  const element = event.currentTarget;
  const rect = element.getBoundingClientRect();
  element.style.setProperty(
    "--lg-pointer-x",
    `${((event.clientX - rect.left) / rect.width) * 100}%`,
  );
  element.style.setProperty(
    "--lg-pointer-y",
    `${((event.clientY - rect.top) / rect.height) * 100}%`,
  );
}

export function LiquidGlass({
  as = "div",
  children,
  className = "",
  tone = "light",
  intensity = "soft",
  interactive = true,
  onPointerMove,
  ...props
}: LiquidGlassProps) {
  const Element = as as ElementType;

  return createElement(
    Element,
    {
      ...props,
      className: ["liquid-glass", className].filter(Boolean).join(" "),
      "data-intensity": intensity,
      "data-tone": tone,
      onPointerMove: (event: PointerEvent<HTMLElement>) => {
        if (interactive) setSpecularPosition(event);
        onPointerMove?.(event);
      },
    },
    <span className="liquid-glass__content">{children}</span>,
  );
}
